; WarmupMapScaleLowSpeed ($0A66): 2D table, 5 points, unsigned
; MAP to row position of WarmupMapCoolantLowSpeed
; x: kpa, y: pos256 (units: docs/en/calibration.md)
; Inputs: Map
; Read at $10E2E
;---------------------------------------------------------------------------------------------------
WarmupMapScaleLowSpeed:
        dc.b    5,$80                                    ; points, flags
        dc.b    120,0, 166,64, 190,128, 206,192, 235,255 ; x, y

        dc.b    $00,$82,$01,$04
RunPeriodOn:
        dc.b    $00,$C3                                  ; Crank ISR (Isr_GPT_IC1): reference period (RefPeriod, word) below which the engine counts as running
RunPeriodOff:
        dc.b    $01,$87                                  ; Crank ISR: reference period at or above which the engine counts as stopped
CrankCoolantFloor:
        dc.b    $63                                      ; Cranking fuel: CrankCoolant is raised to at least this value while the throttle is not closed
CrankClearFloodThrottle:
        dc.b    $80                                      ; Cranking: throttle above this value clears the cranking pulse (clear flood)
HotRestartCoolantMin:
        dc.b    $58                                      ; Coolant at or above which EngineStateFlags bit 4 (warm engine for the per-event fuel) sets
        dc.b    $01
FuelEventCoolantMax:
        dc.b    $58                                      ; Per-event fuel: the coolant correction of FuelEventCalc applies below this coolant
FuelEventColdOffset:
        dc.b    $6E                                      ; Per-event fuel (FuelEventCalc): value minus 110 gives the cold correction step
FuelEventColdOffset2:
        dc.b    $6E                                      ; Per-event fuel: second value minus 110 used below FuelEventCoolantMax
FuelEventOffsetIn:
        dc.b    $44                                      ; Input value of FuelEventOffset (and of the cranking event timing); bit $0338.2 selects FuelEventOffsetInAlt
CrankFuelBattTempMax:
        dc.b    $58                                      ; Cranking fuel: battery temperature at or below which the extra term (ScratchC) applies

