; Vector $11
;---------------------------------------------------------------------------------------------------
Isr_IRQ1:
        ORP     #$00E0
        PSHM    D,X,K
        BCLR    >PFPAR,Z,#$02                            ; bit 1: port F pin 1 function (set = IRQ1 input)
        BCLR    >DDRF,Z,#$02                             ; bit 1: port F pin 1 direction (set = output)
        LDD     #$8000
        LBRA    UnexpectedInterrupt

