Isr_GPT_IC3:
        ORP     #$00E0
        PSHM    D,E,X,Y,K
        LDE     #$0010
        JSR     DelayLoop
        BRSET   >PORTGP,Z,#$04,L08332                    ; bit 2: GPT port pin 2 level (IC3)
        INC     >DistancePulses,Z
        INCW    >Vss052,Z
        BRSET   >Options032D,#$20,L080F4                 ; bit 5: A/C clutch logic on (AcClutchLogicOn); also selects the switch-input map, the VSS constants and the speed control lamp
        TSTW    >Vss052,Z
        BNE     L08104
        BRA     L08100
L080F4:
        LDD     <Vss052,Z
        CPD     #$8333
        BLS     L08104
        CLRW    >Vss052,Z
L08100:
        BSET    >VssFlags,Z,#$04                         ; bit 2: mileage step reached: SRI mileage to be stored (Isr_GPT_IC3, SriMileageStore)
L08104:
        BRSET   >VssFlags,Z,#$02,L08132                  ; bit 1: second VSS pulse seen (Isr_GPT_IC3)
        BRSET   >VssFlags,Z,#$01,L0812C                  ; bit 0: first VSS pulse seen (Isr_GPT_IC3)
        BSET    >VssFlags,Z,#$01                         ; bit 0: first VSS pulse seen (Isr_GPT_IC3)
        CLR     >VssPulseIndex,Z
        LDD     >TIC3,Z
        STD     >VssAB6,Z
        LDD     >VehicleSpeedRaw,Z
        STD     >VssPeriodLast,Z
        LBRA    L08326
L0812C:
        BSET    >VssFlags,Z,#$02                         ; bit 1: second VSS pulse seen (Isr_GPT_IC3)
        BRA     L08136
L08132:
        BSET    >VssFlags,Z,#$08                         ; bit 3: new VSS period to process (Isr_GPT_IC3, cleared by CalcVehicleSpeed)
L08136:
        LDD     >TIC3,Z
        TZX
        TZY
        LDX     #$8AB6
        LDY     #$84F0
        JSR     PeriodChangeTrack
        LDAA    >VssPulseIndex,Z
        LSRA
        STAA    >VssBusValue,Z
        LDE     >TIC3,Z
        SUBE    >VssAB6,Z
        STE     >VssAB4,Z
        CLR     >VssPulseIndex,Z
        LDE     >TIC3,Z
        STE     >VssAB6,Z
        LDE     >VssBusValue2,Z
        LDD     #$E000
        EMUL
        ADCE    #$0000
        XGEX
        LDE     >VssBusValue,Z
        LDAA    >VssAB5,Z
        ROLA
        ROLE
        XGDX
        ADE
        BCC     L08192
        LDE     #$FFFF
L08192:
        STE     >VssBusValue2,Z
        BRCLR   >CrankFlags2,Z,#$08,L081B0               ; bit 3: VSS period long ($07D0 or more) not seen (Isr_GPT_IC3); HighRpmTimerUpdate counts HighRpmTimer2
        LDD     >VssAA9,Z
        ADDD    #$01
        STD     >VssAA9,Z
        CPD     #$07D0
        BCS     L081B0
        BCLR    >CrankFlags2,Z,#$08                      ; bit 3: VSS period long ($07D0 or more) not seen (Isr_GPT_IC3); HighRpmTimerUpdate counts HighRpmTimer2
L081B0:
        BRCLR   >CrankFlags2,Z,#$20,L081C2               ; bit 5: vehicle speed or bus speed value high (Isr_GPT_IC3); HighRpmTimerUpdate counts
        LDAA    >VehicleSpeed,Z
